{
  "status": "SUPPORTED",
  "task_summary": "Locate a fastening tool, fasten a component to a marked location on the workbench, and leave the tool on the workbench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "An implement used to secure parts together.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["screwdriver", "wrench", "clamp", "adhesive"],
        "required_properties": ["can_apply_force", "can_secure_component"]
      },
      {
        "id": "component",
        "entity_kind": "OBJECT",
        "function": "The object being secured or joined.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["block", "part", "piece"],
        "required_properties": ["can_be_fastened"]
      },
      {
        "id": "workbench",
        "entity_kind": "REGION",
        "function": "The surface where the task takes place.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["table", "desk", "bench"],
        "required_properties": ["is_flat", "supports_objects"]
      },
      {
        "id": "fastening_location",
        "entity_kind": "REGION",
        "function": "The specific area on the workbench where the fastening occurs.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["spot", "area", "zone"],
        "required_properties": ["is_on_workbench", "is_marked"]
      }
    ],
    "functional_relations": [
      {
        "id": "is_compatible_for_fastening",
        "relation": "is_compatible_with",
        "participant_roles": [
          "fastening_tool",
          "component"
        ]
      ,
        "required": true
      },
      {
        "id": "is_fastened_to",
        "relation": "is_attached_to",
        "participant_roles": [
          "component",
          "fastening_location"
        ]
      ,
        "required": true
      },
      {
        "id": "is_left_on",
        "relation": "is_resting_on",
        "participant_roles": [
          "fastening_tool",
          "workbench"
        ]
      ,
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "fasten_operation",
        "operation": "fasten",
        "participant_roles": [
          "fastening_tool",
          "component",
          "fastening_location"
        ]
      ,
        "operation_count": 1
      },
      {
        "id": "place_operation",
        "operation": "place",
        "participant_roles": [
          "fastening_tool",
          "workbench"
        ]
      ,
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "fastening_tool": [],
      "component": [
        {
          "label": "items_in_tray",
          "visual_description": "Yellow and blue rectangular objects on a black tray."
        }
      ],
      "workbench": [
        {
          "label": "wooden_table",
          "visual_description": "Wooden table surface with drawers underneath."
        }
      ],
      "fastening_location": [
        {
          "label": "tray_area",
          "visual_description": "Area on the table where the tray sits."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "cabinet",
        "label": "Blue cabinet",
        "visual_description": "Tall blue cabinet behind the table.",
        "reason": "Closed storage structure; likely contains tools or components."
      },
      {
        "id": "drawer_left",
        "label": "Left drawer",
        "visual_description": "Blue drawer under the left side of the table.",
        "reason": "Closed storage structure; likely contains tools or components."
      },
      {
        "id": "drawer_right",
        "label": "Right drawer",
        "visual_description": "Blue drawer under the right side of the table.",
        "reason": "Closed storage structure; likely contains tools or components."
      }
    ],
    "inspection_order": [
      "cabinet",
      "drawer_left",
      "drawer_right"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
